package com.airesumebuilder.feature.subscription.repository;import com.airesumebuilder.common.exception.ResourceNotFoundException;import com.airesumebuilder.feature.subscription.service.SubscriptionService.Subscription;import java.sql.*;import java.time.Instant;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class SubscriptionRepository{private final JdbcTemplate jdbc;public SubscriptionRepository(JdbcTemplate j){jdbc=j;}public Subscription current(String email){return jdbc.query("SELECT s.* FROM subscriptions s JOIN users u ON u.id=s.user_id WHERE u.email=? AND s.is_current=TRUE",this::map,email).stream().findFirst().orElse(null);}public Subscription createFree(String email){int n=jdbc.update("INSERT INTO subscriptions(user_id,plan,status,starts_at,is_current,created_at,updated_at) SELECT id,'FREE','ACTIVE',NOW(6),TRUE,NOW(6),NOW(6) FROM users WHERE email=? AND deleted_at IS NULL",email);if(n==0)throw new ResourceNotFoundException("User account not found.");return current(email);}public List<Subscription>history(String email){return jdbc.query("SELECT s.* FROM subscriptions s JOIN users u ON u.id=s.user_id WHERE u.email=? ORDER BY s.starts_at DESC",this::map,email);}public void cancelCurrent(String email){if(jdbc.update("UPDATE subscriptions s JOIN users u ON u.id=s.user_id SET s.status='CANCELLED',s.is_current=FALSE,s.ends_at=NOW(6),s.updated_at=NOW(6) WHERE u.email=? AND s.is_current=TRUE",email)==0)throw new ResourceNotFoundException("Current subscription not found.");}private Subscription map(ResultSet r,int n)throws SQLException{Timestamp end=r.getTimestamp("ends_at");return new Subscription(r.getLong("id"),r.getString("plan"),r.getString("status"),r.getBoolean("is_current"),r.getTimestamp("starts_at").toInstant(),end==null?null:end.toInstant());}}
